    agent_name: row.agentName,
    product_name: row.productName,
    qty: row.qty,
    unit_price_cents: row.unitPriceCents,
    total_cents: row.totalCents,
    status: row.status,
    reason: row.reason,
    idempotency_key: row.idempotencyKey,
